def step(context):
    year = context['period']
    observation = context['inputs']['observations'][0]['payload']
    if observation['year'] != year:
        raise ValueError('publication registry requires the current-year native observation')
    records = []
    for conference in observation['conferences']['conferences']:
        for paper in conference['submitted_papers']:
            reviews = conference['reviews'].get(paper['id'], [])
            scores = [float(review['overall_score']) for review in reviews]
            score = sum(scores) / len(scores) if scores else 0.0
            records.append({'payload': {'paper_id': paper['id'], 'conference_id': conference['conference_id'], 'decision': 'accept', 'final_score': score}, 'artifact_ids': [paper['id']]})
    if not records:
        records = [{'payload': {'empty_cycle': True}}]
    return {'outputs': {'next': [{'payload': {'year': year}}], 'decisions': records}, 'state': {'last_year': year, 'accepted_paper_ids': [item['payload']['paper_id'] for item in records if 'paper_id' in item['payload']]}}
